216:/** Hemi-octahedral map of a unit direction with y >= 0 -> [0, 1]^2 (the same formula as the shader). */
217:export function hemiOctEncode(d: [number, number, number]): [number, number] {
218:  const s = Math.abs(d[0]) + Math.abs(d[2]) + Math.max(d[1], 0);
219:  const px = d[0] / s;
220:  const pz = d[2] / s;
221:  return [(px + pz) * 0.5 + 0.5, (px - pz) * 0.5 + 0.5];
222:}
