33:/**
34: * Leaf atlas (alpha = leaf mask, grey = shading, the vertex colour tints it). Left half: one cluster (needle spray
35: * along v / leaves splayed from the bottom centre); right half: a dense patch of clusters (merged and crown cards).
36: */
37:export function foliageTexture(kind: FoliageKind): Texture {
38:  let t = textures.get(`leaf:${kind}`);
39:  if (t) return t;
40:  const S = 128;
41:  const W = S * 2;
42:  const alpha = new Float32Array(W * S);
43:  const shade = new Float32Array(W * S).fill(1);
44:  const stamp = (cx: number, cy: number, r: number, v: number, x0: number) => {
45:    for (let y = Math.max(0, Math.floor(cy - r)); y <= Math.min(S - 1, Math.ceil(cy + r)); y++)
46:      for (let x = Math.max(0, Math.floor(cx - r)); x <= Math.min(S - 1, Math.ceil(cx + r)); x++) {
47:        const d = Math.sqrt((x - cx) ** 2 + (y - cy) ** 2);
48:        const a = Math.min(1, Math.max(0, r - d + 0.5));
49:        const k = y * W + x0 + x;
50:        if (a > alpha[k]) {
51:          alpha[k] = a;
52:          shade[k] = v;
53:        }
54:      }
55:  };
56:  const line = (x0: number, y0: number, x1: number, y1: number, r: number, v0: number, v1: number, ox: number) => {
57:    const n = Math.ceil(Math.hypot(x1 - x0, y1 - y0) / 0.5);
58:    for (let i = 0; i <= n; i++) {
59:      const f = i / n;
60:      stamp(x0 + (x1 - x0) * f, y0 + (y1 - y0) * f, r, v0 + (v1 - v0) * f, ox);
61:    }
62:  };
63:  const leaf = (cx: number, cy: number, ang: number, l: number, wd: number, v: number, ox: number) => {
64:    // An ellipse along `ang` from (cx, cy), lighter at the tip, with a darker midrib.
65:    const dx = Math.cos(ang);
66:    const dy = Math.sin(ang);
67:    const n = Math.ceil(l / 0.7);
68:    for (let i = 0; i <= n; i++) {
69:      const f = i / n;
70:      const r = wd * Math.sin(Math.PI * Math.min(1, f * 1.05 + 0.02));
71:      stamp(cx + dx * l * f, cy + dy * l * f, Math.max(0.6, r), v * (0.85 + 0.25 * f), ox);
72:    }
73:    line(cx, cy, cx + dx * l * 0.9, cy + dy * l * 0.9, 0.5, v * 0.7, v * 0.8, ox);
74:  };
75:  const spray = (ox: number, cx: number, cy: number, len: number, ang: number, seed: number) => {
76:    // A twig with needles both sides, angled forward.
77:    const dx = Math.cos(ang);
78:    const dy = Math.sin(ang);
79:    line(cx, cy, cx + dx * len, cy + dy * len, 0.9, 0.55, 0.6, ox);
80:    for (let i = 0; i < len / 2.2; i++) {
81:      const f = (i * 2.2) / len;
82:      const px = cx + dx * len * f;
83:      const py = cy + dy * len * f;
84:      for (const side of [-1, 1]) {
85:        const a = ang + side * (0.75 + 0.2 * unit(mix32(seed, i * 2 + (side > 0 ? 1 : 0))));
86:        const nl = len * 0.22 * (1 - f * 0.5);
87:        line(px, py, px + Math.cos(a) * nl, py + Math.sin(a) * nl, 0.55, 0.7, 1.05, ox);
88:      }
89:    }
90:  };
91:  const blob = (ox: number, seed: number) => {
92:    // Dense patch: many small clusters inside a rough round outline.
93:    for (let i = 0; i < 340; i++) {
94:      const a = unit(mix32(seed, i * 3)) * Math.PI * 2;
95:      const r = Math.sqrt(unit(mix32(seed, i * 3 + 1))) * S * 0.44;
96:      const cx = S / 2 + Math.cos(a) * r;
97:      const cy = S / 2 + Math.sin(a) * r * 0.92;
98:      const v = 0.65 + 0.45 * unit(mix32(seed, i * 3 + 2)) * (0.6 + 0.4 * (cy / S));
99:      if (kind === 'needles') spray(ox, cx, cy, 12, a + 1.2, seed + i);
100:      else leaf(cx, cy, a + 2.2, 9, 3.2, v, ox);
101:    }
102:  };
103:  if (kind === 'needles') {
104:    // Spray along v (the card runs along the twig, tip at v = 1).
105:    line(S / 2, 2, S / 2, S - 4, 1.4, 0.5, 0.6, 0);
106:    for (let i = 0; i < 26; i++) {
107:      const y = 6 + i * 4.6;
108:      for (const side of [-1, 1]) {
109:        const a = Math.PI / 2 + side * (0.85 + 0.25 * unit(mix32(7, i * 2 + side)));
110:        const l = 40 * (1 - (i / 26) * 0.45);
111:        line(S / 2, y, S / 2 + Math.cos(a) * l, y + Math.sin(a) * l, 0.75, 0.6, 1.08, 0);
112:      }
113:    }
114:  } else {
115:    // Short twigs splayed from the bottom centre (the twig tip), each with small leaves along it and at its end.
116:    for (let t = 0; t < 4; t++) {
117:      const ta = Math.PI / 2 + (t - 1.5) * 0.42;
118:      const tl = 70 + 30 * unit(mix32(4, t));
119:      const ex = S / 2 + Math.cos(ta) * tl;
120:      const ey = 4 + Math.sin(ta) * tl;
121:      line(S / 2, 4, ex, ey, 0.8, 0.5, 0.55, 0);
122:      for (let i = 0; i < 6; i++) {
123:        const f = 0.3 + i * 0.13;
124:        const side = i % 2 ? 1 : -1;
125:        const a = ta + side * (0.7 + 0.3 * unit(mix32(5, t * 8 + i)));
126:        const l = 20 + 8 * unit(mix32(6, t * 8 + i));
127:        leaf(S / 2 + (ex - S / 2) * f, 4 + (ey - 4) * f, a, l, 6.5, 0.75 + 0.35 * unit(mix32(9, t * 8 + i)), 0);
128:      }
129:      leaf(ex, ey, ta, 24, 7, 0.95, 0);
130:    }
131:  }
132:  blob(S, kind === 'needles' ? 31 : 41);
133:  const data = new Uint8Array(W * S * 4);
134:  for (let k = 0; k < W * S; k++) {
135:    const c = Math.round(Math.min(1, shade[k]) * 255);
136:    data.set([c, c, c, Math.round(alpha[k] * 255)], k * 4);
137:  }
138:  t = new DataTexture(data, W, S);
139:  t.magFilter = LinearFilter;
140:  t.minFilter = LinearMipmapLinearFilter;
141:  t.generateMipmaps = true;
142:  t.colorSpace = SRGBColorSpace;
143:  t.needsUpdate = true;
144:  textures.set(`leaf:${kind}`, t);
145:  return t;
146:}
