148:// --- materials -------------------------------------------------------------------------------------------------
149:
150:const materials = new Map<string, MeshStandardMaterial | MeshDepthMaterial>();
151:let foliageA2C = false;
152:
153:/** Alpha-to-coverage on the leaf cards when the renderer has MSAA (engine/materials.ts `setFoliageAntialias`). */
154:export function setTreeFoliageAntialias(on: boolean): void {
155:  foliageA2C = on;
156:  for (const [k, m] of materials)
157:    if (k.startsWith('leaf:') && m.alphaToCoverage !== on) {
158:      m.alphaToCoverage = on;
159:      m.needsUpdate = true;
160:    }
161:}
162:
163:export function barkMaterial(kind: BarkTexture): MeshStandardMaterial {
164:  const key = `bark:${kind}`;
165:  let m = materials.get(key) as MeshStandardMaterial | undefined;
166:  if (m) return m;
167:  m = new MeshStandardMaterial({ vertexColors: true, map: barkTexture(kind), roughness: 0.95 });
168:  m.name = `tree ${key}`;
169:  hookStandard(m, 'tree-bark-v1', false);
170:  materials.set(key, m);
171:  return m;
172:}
173:
174:export function foliageMaterial(kind: FoliageKind): MeshStandardMaterial {
175:  const key = `leaf:${kind}`;
176:  let m = materials.get(key) as MeshStandardMaterial | undefined;
177:  if (m) return m;
178:  m = new MeshStandardMaterial({
179:    vertexColors: true,
180:    map: foliageTexture(kind),
181:    alphaTest: 0.5,
182:    side: DoubleSide,
183:    roughness: 0.85,
184:  });
185:  m.name = `tree ${key}`;
186:  m.alphaToCoverage = foliageA2C;
187:  m.defines = { TREE_LEAF: 1, RALLY_FOLIAGE: 0.45 };
188:  hookStandard(m, 'tree-leaf-v1', true);
189:  materials.set(key, m);
190:  return m;
191:}
192:
193:/** Shadow-pass material of tree meshes: wind, the shadow level fade and (leaves) the alpha test three copies over. */
194:export function treeDepthMaterial(leaf: boolean): MeshDepthMaterial {
195:  const key = `depth:${leaf}`;
196:  let m = materials.get(key) as MeshDepthMaterial | undefined;
197:  if (m) return m;
198:  m = new MeshDepthMaterial({ depthPacking: RGBADepthPacking });
199:  m.defines = { TREE_SHADOW_PASS: 1, ...(leaf ? { TREE_LEAF: 1 } : {}) };
200:  m.onBeforeCompile = (shader) => {
201:    addWorldUniforms(shader);
202:    Object.assign(shader.uniforms, treeUniforms);
203:    injectVertex(shader, true);
204:    injectFragment(shader);
205:  };
206:  m.customProgramCacheKey = () => `tree-depth-v1-${leaf}`;
207:  materials.set(key, m);
208:  return m;
209:}
