211:// --- impostor --------------------------------------------------------------------------------------------------
212:
213:/** Octahedral impostor atlas: N x N frames over the upper hemisphere (trees/impostor.ts bakes them). */
214:export const IMPOSTOR_FRAMES = 8;
215:
216:/** Hemi-octahedral map of a unit direction with y >= 0 -> [0, 1]^2 (the same formula as the shader). */
217:export function hemiOctEncode(d: [number, number, number]): [number, number] {
218:  const s = Math.abs(d[0]) + Math.abs(d[2]) + Math.max(d[1], 0);
219:  const px = d[0] / s;
220:  const pz = d[2] / s;
221:  return [(px + pz) * 0.5 + 0.5, (px - pz) * 0.5 + 0.5];
222:}
223:
224:export function hemiOctDecode(u: number, v: number): [number, number, number] {
225:  const fx = u * 2 - 1;
226:  const fy = v * 2 - 1;
227:  const x = (fx + fy) * 0.5;
228:  const z = (fx - fy) * 0.5;
229:  const y = 1 - Math.abs(x) - Math.abs(z);
230:  const l = Math.sqrt(x * x + y * y + z * z);
231:  return [x / l, y / l, z / l];
232:}
233:
234:const IMPOSTOR_VERTEX = /* glsl */ `
235:	// Billboard around the bounding sphere centre, facing the camera, upright like the bake cameras.
236:	vec3 tiCenter = tOrigin + vec3( 0.0, tlSphere.x * tScale, 0.0 );
237:	vec3 tiToCam = normalize( cameraPosition - tiCenter );
238:	vec3 tiRight = cross( vec3( 0.0, 1.0, 0.0 ), tiToCam );
239:	tiRight = dot( tiRight, tiRight ) > 1e-6 ? normalize( tiRight ) : tRot * vec3( 1.0, 0.0, 0.0 );
240:	vec3 tiUp = cross( tiToCam, tiRight );
241:	float tiR = tlSphere.y * tScale;
242:	vec3 tiWorld = tiCenter + ( tiRight * position.x + tiUp * position.y ) * tiR;
243:	// Trunk sway at this corner's height above the foot (object space), the same as the geometry levels.
244:	tiWorld += tWindW * treeTrunk( ( tiWorld.y - tOrigin.y ) / tScale, treeInst.z, tGust ) * tScale;
245:	vec4 mvPosition = viewMatrix * vec4( tiWorld, 1.0 );
246:	gl_Position = projectionMatrix * mvPosition;
247:	// Frames: the 4 grid directions around the object-space view direction, bilinear weights.
248:	vec3 tiDir = transpose( tRot ) * tiToCam;
249:	tiDir.y = max( tiDir.y, 0.0 );
250:	float tiS = abs( tiDir.x ) + abs( tiDir.z ) + tiDir.y;
251:	vec2 tiP = tiDir.xz / tiS;
252:	vec2 tiGrid = ( vec2( tiP.x + tiP.y, tiP.x - tiP.y ) * 0.5 + 0.5 ) * ( TREE_FRAMES - 1.0 );
253:	vec2 tiF0 = min( floor( tiGrid ), vec2( TREE_FRAMES - 2.0 ) );
254:	vTiFrame = tiF0;
255:	vTiWeight = tiGrid - tiF0;
256:	vTiUv = position.xy * 0.5 + 0.5;
257:	vTiRot0 = tRot[ 0 ];
258:	vTiRot1 = tRot[ 1 ];
259:	vTiRot2 = tRot[ 2 ];
260:	vTiDepth = tiR;
261:	vTiToCamView = normalize( ( viewMatrix * vec4( tiToCam, 0.0 ) ).xyz );
262:`;
263:
264:const IMPOSTOR_FRAGMENT = /* glsl */ `
265:	vec4 tiAlbedo = vec4( 0.0 );
266:	vec4 tiNormal = vec4( 0.0 );
267:	for ( int k = 0; k < 4; k ++ ) {
268:		vec2 off = vec2( float( k % 2 ), float( k / 2 ) );
269:		float w = mix( 1.0 - vTiWeight.x, vTiWeight.x, off.x ) * mix( 1.0 - vTiWeight.y, vTiWeight.y, off.y );
270:		vec2 uvA = ( vTiFrame + off + clamp( vTiUv, 0.002, 0.998 ) ) / TREE_FRAMES;
271:		tiAlbedo += texture2D( tlAlbedo, uvA ) * w;
272:		tiNormal += texture2D( tlNormal, uvA ) * w;
273:	}
274:	if ( tiAlbedo.a < 0.5 ) discard;
275:	diffuseColor.rgb = tiAlbedo.rgb / max( tiAlbedo.a, 1e-3 );
276:	diffuseColor.a = 1.0;
277:`;
278:
279:/** Per-variant impostor material: its two atlases (albedo + coverage, object-space normal + depth). */
280:export function impostorMaterial(
281:  albedo: Texture,
282:  normal: Texture,
283:  sphere: { cy: number; r: number },
284:): MeshStandardMaterial {
285:  const m = new MeshStandardMaterial({ roughness: 0.9 });
286:  m.name = 'tree impostor';
287:  m.defines = { TREE_IMPOSTOR: 1, TREE_FRAMES: `${IMPOSTOR_FRAMES}.0`, RALLY_FOLIAGE: 0.45 };
288:  const uniforms = {
289:    tlAlbedo: { value: albedo },
290:    tlNormal: { value: normal },
291:    tlSphere: { value: new Vector2(sphere.cy, sphere.r) },
292:  };
293:  m.onBeforeCompile = (shader) => {
294:    addWorldUniforms(shader);
295:    Object.assign(shader.uniforms, treeUniforms, uniforms);
296:    const vary = /* glsl */ `
297:varying vec2 vTiFrame;
298:varying vec2 vTiWeight;
299:varying vec2 vTiUv;
300:varying vec3 vTiRot0;
301:varying vec3 vTiRot1;
302:varying vec3 vTiRot2;
303:varying float vTiDepth;
304:varying vec3 vTiToCamView;
305:`;
306:    injectVertex(shader, false);
307:    shader.vertexShader = shader.vertexShader
308:      .replace('#include <common>', `#include <common>\nuniform vec2 tlSphere;\n${vary}`)
309:      .replace('#include <project_vertex>', `${IMPOSTOR_VERTEX}\n${VERTEX_COLLAPSE}`)
310:      .replace('#include <worldpos_vertex>', 'vec4 worldPosition = vec4( tiWorld, 1.0 );');
311:    injectFragment(shader);
312:    shader.fragmentShader = shader.fragmentShader
313:      .replace(
314:        '#include <common>',
315:        `#include <common>\nuniform sampler2D tlAlbedo;\nuniform sampler2D tlNormal;\nuniform mat4 projectionMatrix;\n${vary}`,
316:      )
317:      .replace('#include <map_fragment>', `#include <map_fragment>\n${IMPOSTOR_FRAGMENT}\n${FRAGMENT_COLOR}`)
318:      .replace(
319:        '#include <normal_fragment_begin>',
320:        `#include <normal_fragment_begin>
321:	vec3 tiN = mat3( vTiRot0, vTiRot1, vTiRot2 ) * ( tiNormal.xyz / max( tiAlbedo.a, 1e-3 ) * 2.0 - 1.0 );
322:	normal = normalize( ( viewMatrix * vec4( tiN, 0.0 ) ).xyz );
323:	nonPerturbedNormal = normal;
324:	// Depth: the baked surface sits this far in front of / behind the billboard plane.
325:	vec3 tiView = - vViewPosition + vTiToCamView * ( ( tiNormal.w / max( tiAlbedo.a, 1e-3 ) ) * 2.0 - 1.0 ) * vTiDepth;
326:	vec4 tiClip = projectionMatrix * vec4( tiView, 1.0 );
327:	gl_FragDepth = clamp( tiClip.z / tiClip.w * 0.5 + 0.5, 0.0, 1.0 );`,
328:      );
329:  };
330:  m.customProgramCacheKey = () => 'tree-impostor-v2';
331:  return m;
332:}

